  pl:[['Jaki jest bonus GrandWin?','Do 1 200 € i 150 spinów na cztery wpłaty: 125%, 50%, 50% i 100%, każda do 300 €.'],['Jaki jest obrót?','Wpłata plus bonus 40x w 21 dni; stawka do 12 € lub 5% bonusu.'],['Jak dzieli się 150 spinów?','50, 25, 25 i 50 na kolejnych etapach; ważne siedem dni. Gry sprawdź w ofercie.'],['Jaki jest limit wypłat?','5 000 € łącznie w ruchomym okresie siedmiu dni, o ile nie podano inaczej.'],['Czy możliwa jest opłata?','Tak. Bez obrotu wpłaty 5x możliwa odmowa lub opłata do 8%.']],
  uk:[['Який бонус GrandWin?','До 1 200 € і 150 фріспінів на чотири депозити: 125%, 50%, 50% і 100%, кожен до 300 €.'],['Який відіграш?','Депозит плюс бонус 40x за 21 день; ставка до 12 € або 5% бонусу.'],['Як розподілено 150 фріспінів?','50, 25, 25 і 50 за етапами; діють сім днів. Ігри перевіряйте в активній пропозиції.'],['Який ліміт виплат?','5 000 € загалом за ковзні сім днів, якщо прямо не вказано інше.'],['Чи можлива комісія?','Так. Без відіграшу депозиту 5x виплату можуть відхилити або стягнути до 8%.']],
  pt:[['Qual é o bónus GrandWin?','Até 1.200 € e 150 jogadas em quatro depósitos: 125%, 50%, 50% e 100%, cada um até 300 €.'],['Qual é o rollover?','Depósito mais bónus 40x em 21 dias; aposta máxima 12 € ou 5% do bónus.'],['Como se dividem as 150 jogadas?','50, 25, 25 e 50 por etapa; expiram em sete dias. Confirme os jogos na oferta ativa.'],['Qual é o limite de levantamento?','5.000 € no total por sete dias móveis, salvo indicação expressa em contrário.'],['Pode haver comissão?','Sim. Sem jogar o depósito 5x, o pedido pode ser recusado ou ter taxa até 8%.']],
