const buildPage = (locale, c, template) => {
  const pageFaq = [...faqFacts[locale], c.faq[5], c.faq[6], [c.faq[7][0], safetyFacts[locale][2][1]]];
  const pagePath = `${routePrefix(locale)}brands/grandwin/`;
  const url = `https://spincresta.com/${pagePath}`;
  const header = template.match(/<header class="header">[\s\S]*?<\/header>/)?.[0];
  const footer = template.match(/<footer class="footer">[\s\S]*?<\/footer>/)?.[0];
  if (!header || !footer) throw new Error(`Header/footer missing for ${locale}`);
  const authorUrl = `https://spincresta.com/${routePrefix(locale)}authors/odri-chambers/`;
  const graph = {'@context':'https://schema.org','@graph':[
    {'@type':'Organization','@id':'https://spincresta.com/#organization',name:'SpinCresta',url:'https://spincresta.com/',logo:{'@type':'ImageObject',url:'https://spincresta.com/favicon.png'}},
    {'@type':'WebSite','@id':'https://spincresta.com/#website',name:'SpinCresta',url:'https://spincresta.com/',publisher:{'@id':'https://spincresta.com/#organization'}},
    {'@type':'Person','@id':`${authorUrl}#person`,name:'Odri Chambers',url:authorUrl},
    {'@type':'WebPage','@id':`${url}#webpage`,url,name:c.title,description:c.description,dateModified:'2026-10-01',inLanguage:c.lang,isPartOf:{'@id':'https://spincresta.com/#website'},mainEntity:{'@id':`${url}#article`},reviewedBy:{'@id':`${authorUrl}#person`}},
    {'@type':'Article','@id':`${url}#article`,headline:c.title,description:c.description,image:screenshot,datePublished:'2026-10-01',dateModified:'2026-10-01',inLanguage:c.lang,author:{'@id':`${authorUrl}#person`},publisher:{'@id':'https://spincresta.com/#organization'},mainEntityOfPage:{'@id':`${url}#webpage`},about:{'@type':'Thing',name:'GrandWin'}},
    {'@type':'BreadcrumbList','@id':`${url}#breadcrumb`,itemListElement:[{'@type':'ListItem',position:1,name:'SpinCresta',item:`https://spincresta.com/${routePrefix(locale)}`},{'@type':'ListItem',position:2,name:c.h1,item:url}]},
    {'@type':'FAQPage','@id':`${url}#faq`,mainEntity:pageFaq.map(([q,a])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:a}}))},
  ]};
  const alternates = [['en',''],['de','de/'],['es','es/'],['it','it/'],['pl','pl/'],['uk','uk/'],['pt','pt/'],['fr','fr/'],['hi','hi/'],['fi-FI','fi/'],['x-default','']].map(([lang,prefix])=>`    <link rel="alternate" hreflang="${lang}" href="https://spincresta.com/${prefix}brands/grandwin/" />`).join('\n');
  const head = `<!doctype html>\n<html lang="${c.lang}">\n  <head>\n    <meta charset="UTF-8" />\n    <script async src="https://www.googletagmanager.com/gtag/js?id=G-5NWTMCZ14N"></script>\n    <script>window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments)}gtag('js',new Date());gtag('config','G-5NWTMCZ14N');</script>\n    <meta name="viewport" content="width=device-width, initial-scale=1" />\n    <meta name="theme-color" content="#080d1f" />\n    <meta name="robots" content="index, follow, max-image-preview:large" />\n    <title>${esc(c.title)}</title>\n    <meta name="description" content="${esc(c.description)}" />\n    <meta name="keywords" content="${esc(c.keywords)}" />\n    <link rel="canonical" href="${url}" />\n${alternates}\n    <link rel="icon" type="image/png" sizes="64x64" href="/favicon.png" />\n    <meta property="og:type" content="article" />\n    <meta property="og:title" content="${esc(c.title)}" />\n    <meta property="og:description" content="${esc(c.description)}" />\n    <meta property="og:url" content="${url}" />\n    <meta property="og:image" content="${screenshot}" />\n    <meta property="og:site_name" content="SpinCresta" />\n    <meta name="twitter:card" content="summary_large_image" />\n    <meta name="twitter:title" content="${esc(c.title)}" />\n    <meta name="twitter:description" content="${esc(c.description)}" />\n    <meta name="twitter:image" content="${screenshot}" />\n    <meta name="brand-snapshot-intro" content="${esc(c.description)}" />\n    <link rel="stylesheet" href="/styles.css?v=20261001-grandwin-1" />\n    <script type="application/ld+json">${JSON.stringify(graph)}</script>\n  </head>\n`;
  const features = c.features.map(([title,text],index)=>`<div class="feature-card glass-card"><div class="icon-placeholder">0${index+1}</div><strong>${esc(title)}</strong><span>${esc(text)}</span></div>`).join('');
  const sections = [
    section('grandwin-verdict',c.labels.verdict,c.verdictIntro,table(tableHeads[locale],c.verdict)),
    section('grandwin-bonus',c.labels.bonus,c.bonusIntro,table(offerHeads[locale],c.bonus)),
    section('grandwin-games',c.labels.games,'',cards(c.games)),
    section('grandwin-sports',c.labels.sports,'',cards(c.sports)),
    section('grandwin-payments',c.labels.cashier,c.cashierIntro,table(tableHeads[locale],cashierFacts[locale])),
    section('grandwin-safety',c.labels.safety,'',cards(safetyFacts[locale])),
    section('pros-cons',c.labels.pros,'',`<div class="features-grid premium-grid pros-cons-grid"><div class="feature-card glass-card"><strong>${prosLabels[locale][0]}</strong>${c.pros.map(item=>`<span>- ${esc(item)}</span>`).join('<br />')}</div><div class="feature-card glass-card"><strong>${prosLabels[locale][1]}</strong>${c.cons.map(item=>`<span>- ${esc(item)}</span>`).join('<br />')}</div></div>`),
    section('faq',c.labels.faq,'',`<div class="timeline">${pageFaq.map(([q,a])=>`<h3>${esc(q)}</h3><p>${esc(a)}</p>`).join('')}</div>`),
    `<section class="container"><div class="final-cta-glass"><h2 class="title">${esc(c.labels.final)}</h2><div class="view-all-wrapper"><a href="${affiliate}" class="cta-brands" target="_blank" rel="noopener noreferrer nofollow sponsored">${esc(c.labels.cta)}</a></div></div></section>`,
  ].join('\n');
  return `${head}<body data-brand="grandwin"${locale==='en'?'':` data-language="${locale}"`}>\n${header}\n<section class="hero container"><div class="hero-content glass-card"><div class="brand-logo-container hero-logo"><img class="brand-logo" src="${logo}" alt="GrandWin logo" width="640" height="320" loading="eager" fetchpriority="high" decoding="async" /></div><h1>${esc(c.h1)}</h1><p class="hero-subtitle">${esc(c.intro)}</p><p class="hero-subtitle editorial-meta">${esc(c.editorial)}</p><div class="hero-cta-wrapper"><a href="${affiliate}" class="cta-brands" target="_blank" rel="noopener noreferrer nofollow sponsored">${esc(c.labels.cta)}</a></div></div></section>\n<section class="container features-section glass-section" id="brand-why-section"><div class="brand-why-heading"><h2 class="title">${esc(c.labels.why)}</h2><button class="brand-why-media" type="button" aria-expanded="false" aria-controls="brand-why-section" aria-label="GrandWin"><img src="${screenshot}" alt="${esc(c.imageAlt)}" width="3024" height="1660" loading="eager" fetchpriority="high" decoding="async" /></button></div><div class="features-grid premium-grid">${features}</div></section>\n<section class="container"><div class="brand-countries"><h2 class="title">${esc(c.labels.countries)}</h2><div class="countries-container" id="brand-countries"></div></div></section>\n<section class="container"><div class="brand-payments"><h2 class="title">${esc(c.labels.payments)}</h2><div class="payments-container" id="brand-payments"></div></div></section>\n<main class="content-review">${sections}</main>\n<section class="all-countries"><div class="container"><h2 class="title">${esc(c.labels.allCountries)}</h2><div class="countries-cloud"></div></div></section>\n${footer}\n<script type="module" src="/scripts/main.js?v=20261001-grandwin-1"></script>\n</body>\n</html>\n`;
};

for (const locale of locales) {
  const file = `${routePrefix(locale)}brands/grandwin/index.html`;
  const template = fs.readFileSync(file,'utf8');
  fs.writeFileSync(file,buildPage(locale,copy[locale],template));
  console.log(`Built ${file}`);
}

const catalogBonus = {
  en:'Up to €1,200 + 150 Free Spins',
  de:'Bis zu 1.200 € + 150 Freispiele',
  es:'Hasta 1.200 € + 150 giros gratis',
  it:'Fino a 1.200 € + 150 giri gratis',
  pl:'Do 1 200 € + 150 darmowych spinów',
  uk:'До 1 200 € + 150 фріспінів',
  pt:'Até 1.200 € + 150 jogadas grátis',
  fr:'Jusqu’à 1 200 € + 150 tours gratuits',
  hi:'€1,200 तक + 150 फ्री स्पिन',
  fi:'Enintään 1 200 € + 150 ilmaiskierrosta',
};

for (const locale of locales) {
  const file = `${routePrefix(locale)}casinos-and-betting/index.html`;
  const html = fs.readFileSync(file,'utf8');
  let found = false;
  const updated = html.replace(
    /<article class="casino-list-row"[^>]*data-brand-slug="grandwin"[\s\S]*?<\/article>/,
    row => {
      found = true;
      let bonusIndex = 0;
      return row.replace(/(<p class="casino-bonus"><strong>[^<]+<\/strong>)[\s\S]*?(<\/p>)/g, (paragraph,start,end) => {
        const value = bonusIndex === 1 ? catalogBonus[locale] : null;
        bonusIndex += 1;
        return value === null ? paragraph : `${start} ${value}${end}`;
      });
    },
  );
  if (!found) throw new Error(`${locale}: GrandWin catalog row missing`);
  fs.writeFileSync(file,updated.replace(/\/scripts\/main\.js\?v=[^"']+/g,'/scripts/main.js?v=20261001-grandwin-1'));
}

const countryCodes = new Set(['DE','IT','ES','CH','AT','PT','IE','CA','CL','UY','MX','PE','AR','CO','BR','SE','FI','NO','DK','SK','HU','SA','AE','KW','EG','NL','BE','IS','EE','SI','LV','HR','MD','KZ','UZ','AZ','BA']);
const localePattern = '(?:de|es|it|pl|uk|pt|fr|hi|fi)';
const countryPagePattern = new RegExp(`^(?:${localePattern}/)?online-casinos/[^/]+/index\\.html$`);
const homePages = new Set(['index.html', ...locales.filter(locale => locale !== 'en').map(locale => `${locale}/index.html`)]);
const walk = directory => fs.readdirSync(directory,{withFileTypes:true}).flatMap(entry => {
  if (entry.name.startsWith('.') || entry.name === 'tools') return [];
  const path = directory ? `${directory}/${entry.name}` : entry.name;
  return entry.isDirectory() ? walk(path) : [path];
});
for (const file of walk('.').map(file => file.replace(/^\.\//,'')).filter(file => file === 'index.html' || file.endsWith('/index.html'))) {
  let html = fs.readFileSync(file,'utf8');
  const country = html.match(/<body\b[^>]*\bdata-country="([A-Z]{2})"/)?.[1];
  if (!homePages.has(file) && !(countryPagePattern.test(file) && countryCodes.has(country))) continue;
  const updated = html.replace(/\/scripts\/main\.js\?v=[^"']+/g,'/scripts/main.js?v=20261001-grandwin-1');
  if (updated !== html) fs.writeFileSync(file,updated);
}
